(() => {
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

  // Full-text search index: every heading + section body across all 12 docs pages.
  // Generated from docs/*.html (title + anchor + section text). Works offline on file:// .
  const docsIndex = [{"t": "The interfaces behind the workflow.", "u": "api-docs.html", "s": "DATADOC has one source of truth: the fitted pipeline. The CLI, Python SDK, and local UI all call the same domain objects and enforce the same safety rules. DataDocPipeline PipelineConfig DataDocError Start with the SDK → Copy page", "page": "DATADOC Docs | API Reference", "file": "api-docs.html"}, {"t": "Domain objects", "u": "api-docs.html#objects", "s": "Object Purpose Important fields PipelineConfig Controls target, task, policy, split columns, and resource behavior. target , task , scaling , strict_schema DatasetProfile Describes schema, quality findings, roles, and fingerprint. roles , findings , null_counts TransformPlan Ordered, explainable transformation operations. operations , protected_columns EvaluationReport Compares the baseline and selected preparation choice. metric , split_strategy , improvement DataDocError Actionable compatibility and input-contract failure. message text identifies the failing column or option Python public imports from datadoc import DataDocPipeline, PipelineConfig from datadoc.core.pipeline import ( DataDocError, DatasetProfile, EvaluationReport, TransformPlan, )", "page": "DATADOC Docs | API Reference", "file": "api-docs.html"}, {"t": "Pipeline methods", "u": "api-docs.html#methods", "s": "METHOD pipeline.profile(df) Returns a DatasetProfile . Read-only and safe before fit. METHOD pipeline.plan(df) Returns a TransformPlan with operations, findings, and protected columns. METHOD pipeline.fit(train_df, target=None) Fits train-only state and returns the same pipeline instance. METHOD pipeline.transform(df) Validates schema and applies frozen state. Raises DataDocError when the input contract fails. METHOD pipeline.save(path) / DataDocPipeline.load(path) Serialize and restore an artifact. Save only after fit; load before inference. METHOD pipeline.evaluate(df, target=None) Runs the optional scikit-learn benchmark. Requires datadoc-cli[ml] and a non-null target. estimator_family=\"both\" fits linear and tree models and keeps the stronger validation score. METHOD pipeline.evaluate_ablation(df, target=None) Compares full, no-clip, no-scaling, and minimal variants. Powers datadoc evaluate --ablation . METHOD pipeline.drift_report(df) Schema validation plus median-shift drift issues. Powers datadoc transform --validate and GET /api/pipeline/drift . METHOD pipeline.explain_plan(df) Human-readable English trace of the plan. Powers datadoc plan --explain . METHOD pipeline.profile_to_html(df=None) Small HTML profile widget for Jupyter and marimo notebooks. METHOD pipeline.export_sklearn_artifact(path) Saves a joblib artifact dict. Powers datadoc export --format joblib .", "page": "DATADOC Docs | API Reference", "file": "api-docs.html"}, {"t": "Local UI API endpoints", "u": "api-docs.html#endpoints", "s": "The FastAPI UI uses a local session header. The browser should not create a second transformation implementation. Endpoint Input Returns GET /api/dataset/metadata X-DATADOC-SESSION Loaded file, row/column counts, metadata. GET /api/pipeline/profile Optional target Serialized profile. POST /api/pipeline/plan Pipeline request JSON Serialized plan. POST /api/pipeline/fit Pipeline request JSON Fitted flag, profile, plan, input/output schema. GET /api/pipeline/preview Session header Output schema and preview rows (8 rows). GET /api/pipeline/export/code Session header Text Python wrapper (executable: python pipeline.py in.csv out.csv ). GET /api/pipeline/lineage Session header Train provenance, input/output schema, config, plan operations. GET /api/pipeline/drift Session header Schema check plus median-shift drift issues for numeric columns. GET /api/dataset/export/csv Session header Transformed CSV download (or raw data before fit). JavaScript UI request shape await axios.post(\"/api/pipeline/fit\", { target: \"churn\", task: \"auto\", // auto | classification | regression scaling: \"auto\", // auto | none | standard | robust drop_identifiers: false, deduplicate: false, clip_outliers: false, categorical_threshold: 20, rare_category_min_frequency: 0.0, datetime_cyclical: false, datetime_extract_hour: true, }, { headers: { \"X-DATADOC-SESSION\": \"local\" }, });", "page": "DATADOC Docs | API Reference", "file": "api-docs.html"}, {"t": "Error contract", "u": "api-docs.html#errors", "s": "422 validation error Use when task, scaling, target, file type, or pipeline configuration is invalid. The response detail should tell the user what to change. 400 state error Use when a session exists but a pipeline has not been fitted—for example, requesting a preview before clicking Fit. 404 session error Use when the session header does not map to an initialized local job. Python consumer-side handling try: transformed = pipeline.transform(rows) except DataDocError as error: # Log the artifact version and input schema before retrying. raise RuntimeError(f\"Input contract failed: {error}\") from error", "page": "DATADOC Docs | API Reference", "file": "api-docs.html"}, {"t": "API Reference", "u": "api-docs.html", "s": "DATADOC API reference for domain objects, CLI surfaces, UI endpoints, and error contracts. DATADOC has one source of truth: the fitted pipeline. The CLI, Python SDK, and local UI all call the same domain objects and enforce the same safety rules.", "page": "DATADOC Docs | API Reference", "file": "api-docs.html"}, {"t": "Architecture & Codebase", "u": "architecture.html", "s": "This is a comprehensive, file-by-file deep dive into the DATADOC repository. It explains the exact logic powering the backend, the mathematical formulas used by plugins, and how terminal commands execute in the background.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "1. Plugins Subsystem: The Math & Logic", "u": "architecture.html#plugins", "s": "The datadoc/plugins/ directory contains seven isolated, stateless advisor modules using Polars expressions. They inherit from BasePlugin and are discovered via plugins/registry.py (see section 4). The production transforms live in core/pipeline.py with frozen train-only state.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "duplicates.py (Duplicate Detection, priority 05)", "u": "architecture.html#plugins", "s": "Logic: Counts exact duplicate rows with is_duplicated().sum() . With deduplicate=True , the pipeline drops them from training data at fit time so medians and vocabularies are not skewed. Validation data is never deduplicated.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "rare.py (Rare-Category Grouping, priority 42)", "u": "architecture.html#plugins", "s": "Logic: Categories below rare_category_min_frequency (e.g. 0.02) are grouped into __RARE__ before one-hot encoding, capping output width while keeping the signal. Unseen inference values map to the same token.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "outliers.py (IQR Outlier Clipping)", "u": "architecture.html#plugins", "s": "This plugin detects and clips extreme values to prevent them from skewing machine learning models (like Linear Regression) that are sensitive to extreme variances. graph LR A[\"Column Data\"] --> B[\"Calculate Q1 25th %\"] A --> C[\"Calculate Q3 75th %\"] B --> D[\"Calculate IQR = Q3 - Q1\"] C --> D D --> E[\"Lower Bound = Q1 - 1.5 * IQR\"] D --> F[\"Upper Bound = Q3 + 1.5 * IQR\"] E --> G[\"Polars clip_min, clip_max\"] F --> G IQR = Q3 - Q1 Lower Bound = Q1 - (Multiplier * IQR) Upper Bound = Q3 + (Multiplier * IQR) Logic: If a numeric column has a high standard deviation relative to its mean, the plugin uses the polars.Series.quantile() function to find Q1 and Q3. It applies a with_columns(pl.col(c).clip(lower, upper)) operation.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "scaling.py (Standardization)", "u": "architecture.html#plugins", "s": "Machine learning models that use distance metrics (KNN, SVM) or gradient descent (Neural Networks) require features to be on the same numerical scale. This plugin applies Z-score normalization. graph LR A[\"Numeric Column\"] --> B[\"Calculate Mean μ\"] A --> C[\"Calculate Std Dev σ\"] B --> D[\"Value - μ\"] C --> E[\"Divide by σ\"] D --> E E --> F[\"Zero-Mean, Unit-Variance Column\"] Z = (X - μ) / σ Logic: The plugin checks the ratio of max standard deviation to min standard deviation across columns. If the ratio > 10x, it applies scaling. The Polars execution is (pl.col(c) - pl.col(c).mean()) / pl.col(c).std() .", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "missing_values.py (Imputation)", "u": "architecture.html#plugins", "s": "Models crash when they encounter null or NaN . This plugin safely fills holes. graph TD A[\"Null Value Detected\"] --> B{\"Is Numeric?\"} B -->|Yes| C[\"Calculate Median\"] C --> D[\"fill_null(median)\"] B -->|No| E[\"Calculate Mode\"] E --> F[\"fill_null(mode)\"] Logic: Median is used for numerics instead of Mean because Mean is highly sensitive to outliers. Mode (most frequent value) is used for strings/categoricals. Polars code: pl.col(c).fill_null(pl.col(c).median()) .", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "encoders.py (Categorical One-Hot)", "u": "architecture.html#plugins", "s": "Algorithms only understand numbers, not text like \"Red\" or \"Blue\". graph LR A[\"Color Column\"] --> B{\"Cardinality > Threshold?\"} B -->|Yes| C[\"Drop Column ID\"] B -->|No| D[\"Extract Unique: Red, Blue, Green\"] D --> E[\"Create Color_Red = 1/0\"] D --> F[\"Create Color_Blue = 1/0\"] Logic: If a column has too many unique values (e.g., UUIDs), it's dropped to avoid the \"curse of dimensionality\". Otherwise, it iterates through unique strings and does (pl.col(c) == val).cast(pl.Int8).alias(f\"{c}_{val}\") .", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "datetime_feat.py (Time Series Extraction)", "u": "architecture.html#plugins", "s": "Logic: Takes a string column like \"2024-05-12 14:00\" and uses str.to_datetime(strict=False) . It then extracts dt.year() , dt.month() , dt.day() , dt.weekday() — plus dt.hour() only when training data has a real time component — and drops the original column. With datetime_cyclical=True , month/day/weekday/hour also get sin/cos pairs.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "2. CLI Commands: Background Execution Trace", "u": "architecture.html#cli-commands", "s": "When you type commands into the terminal, cli/app.py acts as the orchestrator. Here is exactly what happens step-by-step in the background.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "datadoc profile", "u": "architecture.html#cli-commands", "s": "Load: The CSV/Parquet file is loaded lazily into a Polars DataFrame. Pipeline Init: A DataDocPipeline is instantiated with default PipelineConfig . Analyze: pipeline.profile() is called. This triggers a massive parallel Polars scan measuring null percentages, uniqueness (cardinality), and regex matching to guess column types (Target vs Identifier vs Numeric). Render: The resulting DatasetProfile dataclass is passed to the Rich library, which draws the beautiful terminal table you see on screen.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "datadoc plan", "u": "architecture.html#cli-commands", "s": "Profile: Runs the profile step (above) internally to understand the data. Formulate: pipeline.plan() is called. It looks at the profile. If it sees numeric nulls, it appends a \"missing_values\" step to the TransformPlan . If it sees a categorical column with 5 unique values, it appends an \"encoder\" step. Serialize: The plan is printed to the screen as a sequence of deterministic steps.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "datadoc wizard (guided entry point)", "u": "architecture.html#cli-commands", "s": "Inspect: Loads the dataset and lists columns, row counts, and detected shape. Ask: Prompts for target column, preset ( quick | balanced | linear | tree | time | robust ), identifier policy, scaling, clipping, and rare-category frequency. Persist: Writes the answers to datadoc.toml so the run is reproducible, then delegates to datadoc run . AI policy: there is no code-generating agent. The optional datadoc-cli[ai] extra ( litellm ) is constrained to explaining or ranking already-registered deterministic transformations. Provider-generated Python is never executed by the pipeline.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "datadoc evaluate", "u": "architecture.html#cli-commands", "s": "Split: Splits 80% train / 20% holdout — stratified for classification, ordered for --time-column , group-aware for --group-column . Cross-validate: Runs 3-fold CV on the train split comparing a minimal baseline config (no clipping, no scaling) against the configured candidate. Holdout: Refits the CV winner on full train and scores both on the untouched holdout. Classification uses balanced accuracy (LogisticRegression and/or RandomForest); regression uses negative RMSE (Ridge and/or RandomForestRegressor). Report: Emits an EvaluationReport with metric, split strategy, both scores, improvement, selected pipeline, feature count, and warnings. --ablation additionally compares full, no-clip, no-scaling, and minimal variants.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "3. Core Logic: core/pipeline.py", "u": "architecture.html#core-pipeline", "s": "This is the heart of DATADOC. It defines the DataDocPipeline class and the state models ( DatasetProfile , TransformPlan ). The pipeline enforces a strict 4-phase lifecycle. flowchart TD Raw[(\"Raw DataFrame\")] --> Profile subgraph \"pipeline.py Logic\" Profile[\"1. profile Reads schema, detects column roles, calculates nulls\"] Plan[\"2. plan Formulates strategy based on config thresholds\"] Fit[\"3. fit Learns train-only state: medians, bounds, vocabs\"] Transform[\"4. transform Applies learned state to data via Polars expressions\"] end Profile --> |\"Returns DatasetProfile\"| Plan Plan --> |\"Returns TransformPlan\"| Fit Fit --> Transform Transform --> Clean[(\"ML-Ready DataFrame\")] Fit -.-> |\"Save/Load\"| JSON[(\"pipeline.json state\")] The code is strictly designed to avoid Data Leakage . For example, if you fit a pipeline to training data, the medians calculated during fit() are hardcoded. When transform() is called on validation data, it injects those previously calculated medians rather than recalculating them on the validation data.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "4. Plugin Registry: plugins/registry.py", "u": "architecture.html#core-agent", "s": "Seven deterministic plugins ( DuplicateRemover 05, MissingValue 10, Outlier 20, Datetime 30, CategoricalEncoder 40, RareCategory 42, Scaling 45) implement the BasePlugin lifecycle analyze → recommend → apply as stateless advisors. The registry auto-discovers them plus any third-party plugin registered under the datadoc.plugins entry-point group, sorted by priority. The fitted pipeline in core/pipeline.py — not the plugins — is the production source of truth: it re-implements each transformation with frozen train-only state so validation data can never influence fitted statistics. sequenceDiagram participant User participant CLI as datadoc plugins list participant Registry participant EntryPts as entry-points User->>CLI: datadoc plugins list CLI->>Registry: list_plugins() Registry->>Registry: built-in 7, sort by priority Registry->>EntryPts: load datadoc.plugins group EntryPts-->>Registry: third-party plugins Registry-->>User: priority-ordered table Optional LLM help (via litellm ) is advisory only: it may explain or rank registered transformations, but generated code is never executed.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "5. Removed Legacy: core/engine.py and core/agent.py", "u": "architecture.html#core-engine", "s": "Earlier versions shipped a DATADOC facade ( engine.py ) and an LLM code-executing agent ( agent.py ). Both were deleted in the 0.4.0 leakage-safe refactor: the facade fitted and transformed the same data (a leakage risk), and the agent executed provider-generated Python (a safety risk). New code uses DataDocPipeline directly; see MIGRATION.md for the upgrade path.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "6. Dependencies Explained", "u": "architecture.html#dependencies", "s": "Every dependency in pyproject.toml has a distinct, justified purpose.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "Polars", "u": "architecture.html#dependencies", "s": "Why: Written in Rust, uses the Apache Arrow memory format, and features a lazy evaluation engine. 10-50x faster than Pandas.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "Typer & Rich", "u": "architecture.html#dependencies", "s": "Why: Typer builds CLI tools using Python type hints, while Rich provides beautiful terminal formatting (tables, progress bars, colored text).", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "LiteLLM", "u": "architecture.html#dependencies", "s": "Why: An abstraction layer over LLM APIs. Unifies OpenAI, Anthropic, and Gemini into one interface.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "FastAPI & Uvicorn", "u": "architecture.html#dependencies", "s": "Why: FastAPI provides a blazing fast ASGI web framework to serve API endpoints for the web dashboard.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "Plotext", "u": "architecture.html#dependencies", "s": "Why: Declared terminal-plotting dependency for future in-terminal charts. Current CLI output uses Rich tables and JSON; no chart claims are made by any command today.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "Architecture Deep Dive", "u": "architecture.html", "s": "Low-level deep dive into the DATADOC architecture and codebase. This is a comprehensive, file-by-file deep dive into the DATADOC repository. It explains the exact logic powering the backend, the mathematical formulas used by plugins, and how terminal commands execute in the background.", "page": "DATADOC Docs | Architecture Deep Dive", "file": "architecture.html"}, {"t": "The Command Line Interface, Completely.", "u": "cli.html", "s": "DATADOC provides a local-first, zero-leakage CLI for tabular dataset preparation. Explore parameters, execution mechanics, command breakdowns, and interactive demo testing. datadoc --help Polars Powered Zero Data Leakage v0.5.0 📥 Download demo.csv Explore Transformation Sandbox ↓", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "0. Interactive Demo Sandbox &amp; Test Drive", "u": "cli.html#demo-sandbox", "s": "Download our official 500-row demo.csv test dataset and watch how DATADOC profiles, plans, fits, transforms, and evaluates the dataset step-by-step.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "Download Test Dataset (demo.csv)", "u": "cli.html#demo-sandbox", "s": "Includes missing values, scale mismatches, UUID identifiers, string dates, and extreme outliers (age=999). 📥 Download demo.csv (46 KB) 00. Raw Data 01. Profile 02. Plan 03. Fit (Artifact) 04. Transformed 05. Evaluate Raw Input Dataset: demo.csv (First 5 Rows) Notice the dirty features requiring engineering before machine learning model training: customer_id (ID) name (Text) age salary department city signup_date churn (Target) dba51b99... Person_0 23 57,098 Engineering Hyderabad 2020-07-10 0 4f57a639... Person_1 56 83,878 Engineering Bangalore 2021-11-20 0 10eb978b... Person_2 60 30,695 Support Chennai 2023-07-11 1 e22b64ba... Person_3 null 62,930 Sales Chennai 2022-01-28 1 b88ae03d... Person_4 999 (Outlier) 47,431 Sales Bangalore 2023-02-14 0 Step 1: datadoc profile demo.csv --target churn Profiles dataset health, missing value counts, cardinality, column roles, and generates a unique schema fingerprint. JSON datadoc profile output { \"rows\": 500, \"columns\": 10, \"schema\": { \"customer_id\": \"String\", \"name\": \"String\", \"age\": \"Int64\", \"salary\": \"Int64\", \"department\": \"String\", \"city\": \"String\", \"signup_date\": \"String\", \"churn\": \"Int64\" }, \"null_counts\": { \"age\": 25, \"salary\": 20, \"department\": 15 }, \"roles\": [ { \"name\": \"customer_id\", \"role\": \"identifier\" }, { \"name\": \"name\", \"role\": \"identifier\" }, { \"name\": \"age\", \"role\": \"feature_numeric\" }, { \"name\": \"salary\", \"role\": \"feature_numeric\" }, { \"name\": \"department\", \"role\": \"feature_categorical\" }, { \"name\": \"churn\", \"role\": \"target\" } ], \"schema_fingerprint\": \"a3f890e12d...\" } Step 2: datadoc plan demo.csv --target churn --drop-identifiers Formulates an explicit, explainable sequence of transformation operations with analytical rationales before modifying data. JSON datadoc plan output { \"target\": \"churn\", \"operations\": [ { \"name\": \"DropIdentifiers\", \"columns\": [\"customer_id\", \"name\"], \"rationale\": \"High-cardinality string IDs overfit models and carry zero predictive signal.\" }, { \"name\": \"ImputeNumeric\", \"columns\": [", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "1. Core Concepts &amp; Terminology", "u": "cli.html#concepts", "s": "Before running CLI commands, it is essential to understand the key parameters and arguments that govern DATADOC's behavior.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "Target Column ( --target )", "u": "cli.html#concepts", "s": "The target is the column you intend to predict (e.g., churn , salary , price ). When you declare --target &lt;column&gt; , DATADOC applies a protection boundary to that column. The target is never imputed, scaled, encoded, or clipped. It passes through unchanged so your evaluation metrics and model training remain uncorrupted. Example: In a subscription dataset, churn contains 0 (customer stayed) or 1 (customer left). Passing --target churn prevents DATADOC from scaling or modifying these class labels.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "Task Type ( --task )", "u": "cli.html#concepts", "s": "Defines the nature of the supervised learning task. DATADOC uses this to determine evaluation metrics and optimal default preprocessing routines: auto (Default) : Automatically infers task type. If the target has ≤ 20 unique values or is boolean/string, it selects classification ; otherwise, regression . classification : Supervised binary or multi-class prediction (evaluates via balanced accuracy / log loss). regression : Continuous numeric prediction (evaluates via RMSE / R²).", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "Identifier Dropping ( --drop-identifiers )", "u": "cli.html#concepts", "s": "High-cardinality string IDs (such as customer_id , uuid , user_name ) carry no generalizable predictive signal and cause severe overfitting if one-hot encoded. Passing --drop-identifiers instructs DATADOC to detect string IDs and remove them during transformation.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "Feature Scaling Strategies ( --scaling )", "u": "cli.html#concepts", "s": "Tabular numeric features often vary by orders of magnitude (e.g., age spans 18–80 while income spans 20,000–500,000). Scaling normalizes these ranges: Mode Mathematical Formula Best Used For auto Picks standard for linear models; none for tree models Default — recommended for most workflows none X out = X Tree-based algorithms (RandomForest, XGBoost, LightGBM) standard Z = (X - μ) / σ Linear Regression, Logistic Regression, Neural Networks, SVMs robust Z = (X - Q 2 ) / IQR Datasets containing unclipped, heavy-tailed outliers", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "Outlier Clipping ( --clip-outliers )", "u": "cli.html#concepts", "s": "When enabled, DATADOC calculates upper and lower Interquartile Range (IQR) bounds during fit and clips extreme values during transform : Lower Bound = Q 1 - (1.5 × IQR) Upper Bound = Q 3 + (1.5 × IQR) Values below the lower bound are clamped to the lower bound; values above the upper bound are clamped to the upper bound.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "Split Strategies ( --time-column &amp; --group-column )", "u": "cli.html#concepts", "s": "--time-column &lt;col&gt; : Performs an ordered temporal split (oldest rows in train, newest in test) to prevent future-data leakage in time-series tabular problems. --group-column &lt;col&gt; : Performs group-aware splitting so that all records belonging to a single group (e.g., all visits by patient_id ) reside strictly in train or test.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "2. The Pipeline Lifecycle", "u": "cli.html#workflow", "s": "DATADOC operates on a strict 4-stage lifecycle designed to guarantee zero data leakage between training, validation, and production inference sets. flowchart LR A[\"Raw Dataset (CSV/Parquet)\"] --> B[\"datadoc profile\"] B --> C[\"datadoc plan\"] C --> D[\"datadoc fit (Train Data Only)\"] D --> E[\"pipeline.json (Artifact)\"] E --> F[\"datadoc transform\"] F --> G[\"Clean Dataset\"] 01 Profile Inspect schema, missingness, cardinality, data roles, and compute a schema fingerprint. 02 Plan Formulate a deterministic sequence of operations with explicit analytical rationales. 03 Fit Learn parameters (medians, mode vocabularies, scaling means/stds) strictly from training rows and persist to JSON. 04 Transform Apply the saved JSON artifact immutably to validation, test, or production inference data.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "3. Read-Only Commands", "u": "cli.html#read", "s": "PROFILE datadoc profile &lt;file_path&gt; Inspects a CSV or Parquet file without making any modifications. Generates detailed health reports, column role assignments, missing value counts, and schema fingerprints. Terminal Inspect dataset quality datadoc profile demo.csv --target churn --output profile.json Options Option Type Default Description file_path Argument Required Path to CSV or Parquet input file --target Option None Declare prediction target column to apply protection --output Option None Path to write profile output JSON PLAN datadoc plan &lt;file_path&gt; Generates a transparent, step-by-step transformation plan without modifying the dataset or learning statistics. Terminal Generate transformation plan datadoc plan demo.csv --target churn --drop-identifiers --output plan.json Options Option Type Default Description file_path Argument Required Input CSV or Parquet dataset --target Option None Protected target column name --task Option auto auto , classification , or regression --drop-identifiers Flag False Include identifier dropping in transformation operations --output Option None Path to save plan JSON file", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "4. Build Commands", "u": "cli.html#build", "s": "FIT datadoc fit &lt;file_path&gt; Fits transformation rules (imputation medians, encodings, clipping bounds) strictly on the provided training split and saves a serializable pipeline.json artifact. Terminal Fit pipeline on training data datadoc fit train.csv \\ --target churn \\ --task classification \\ --drop-identifiers \\ --scaling standard \\ --clip-outliers \\ --output artifacts/pipeline.json Options Option Type Default Description file_path Argument Required Path to training CSV/Parquet file --target Option None Supervised target column --task Option auto auto , classification , regression --drop-identifiers Flag False Drop string IDs during pipeline execution --scaling Option auto auto , none , standard , robust --clip-outliers Flag False Opt into upper/lower IQR outlier clipping --output Option pipeline.json Path to save fitted JSON artifact TRANSFORM datadoc transform &lt;file_path&gt; Applies a saved, fitted pipeline artifact to validation, test, or production inference data. Guarantees that validation rows are transformed using training-derived statistics. Terminal Apply pipeline to validation data datadoc transform test.csv \\ --pipeline artifacts/pipeline.json \\ --output clean_test.parquet Options Option Type Default Description file_path Argument Required Path to dataset to transform --pipeline Option Required Path to fitted pipeline.json artifact --output Option Required Output file path ( .csv or .parquet ) EXPORT datadoc export Exports a standalone, self-contained Python script ( pipeline.py ) wrapping the fitted artifact for zero-dependency inference in production environments. Terminal Export standalone Python script datadoc export \\ --pipeline artifacts/pipeline.json \\ --output my_pipeline.py Options Option Type Default Description --pipeline Option Required Path to fitted pipeline.json artifact --output Option pipeline.py Path to write standalone Python script", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "5. Measure &amp; Orchestration Commands", "u": "cli.html#measure", "s": "EVALUATE datadoc evaluate &lt;file_path&gt; Performs a strict 80/20 train/test evaluation comparing a baseline model on raw data against a candidate model trained on DATADOC-cleaned data. flowchart TD Data[\"Raw Dataset\"] --> Split[\"80 / 20 Train-Test Split\"] Split --> RawTrain[\"80% Raw Train\"] Split --> RawTest[\"20% Raw Test\"] RawTrain --> BaseFit[\"Train Baseline Model\"] RawTest --> BaseEval[\"Evaluate Baseline Score\"] RawTrain --> PipeFit[\"Fit Pipeline (Leakage-Safe)\"] PipeFit --> CleanTrain[\"Transform 80% Train\"] PipeFit --> CleanTest[\"Transform 20% Test\"] CleanTrain --> CandFit[\"Train Candidate Model\"] CleanTest --> CandEval[\"Evaluate Candidate Score\"] BaseEval --> Comp[\"Compare & Report Delta\"] CandEval --> Comp Terminal Run evaluation benchmark datadoc evaluate demo.csv \\ --target churn \\ --task classification \\ --estimator tree \\ --output eval_report.json Options Option Type Default Description file_path Argument Required Input CSV or Parquet file --target Option Required Supervised target column to evaluate --task Option auto auto , classification , regression --estimator Option linear linear , tree , or both --time-column Option None Column name for ordered temporal splits --group-column Option None Column name for group-aware splits --output Option None Path to save evaluation report JSON RUN datadoc run &lt;file_path&gt; Orchestrates a complete, one-shot local run: profiles, plans, fits, transforms, and generates a reproducible run directory with manifest files. Terminal Execute reproducible local run datadoc run demo.csv \\ --target churn \\ --output-dir datadoc-run \\ --evaluate Options Option Type Default Description file_path Argument Required Input dataset path --target Option None Target column name --task Option auto auto , classification , regression --output-dir Option datadoc-run Directory path to persist run artifacts --evaluate Flag False Include evaluation benchmark in run output", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "6. Dashboard &amp; Utility Commands", "u": "cli.html#utilities", "s": "UI datadoc ui &lt;file_path&gt; Launches a local FastAPI backend server and opens the interactive Web Dashboard in your default browser. Terminal Launch Web Dashboard datadoc ui demo.csv --port 8000 Options Option Type Default Description file_path Argument Required Dataset file to load in dashboard --port Option 8000 HTTP port for local dashboard server VERSION datadoc version Displays the current installed version of datadoc-cli . Terminal Check DATADOC version datadoc version WIZARD datadoc wizard &lt;file_path&gt; Guided setup: asks for target, preset, identifier/dedup policy, scaling, clipping, and rare-category frequency, writes datadoc.toml , then runs the full pipeline. Terminal Guided first run datadoc wizard train.csv --output-dir datadoc-run Options Option Type Default Description file_path Argument Required Training CSV or Parquet file --output-dir Option datadoc-run Directory for run outputs INIT datadoc init Writes a starter datadoc.toml so runs are reproducible without retyping flags. Settings can also live under [tool.datadoc] in pyproject.toml ; explicit flags always win. Terminal Repeatable config datadoc init --preset balanced --output datadoc.toml LINT datadoc lint &lt;file_path&gt; Lints a dataset for leakage and prep pitfalls: target duplication, null targets, infinite values, duplicate rows, constants, and profile findings. Terminal Leakage lint datadoc lint train.csv --target churn DIFF datadoc diff &lt;file_a&gt; &lt;file_b&gt; Diffs two profile, plan, or pipeline JSON artifacts top-level key by key, plus added/removed plan operations. Terminal Compare artifacts datadoc diff plan-v1.json plan-v2.json PLUGINS datadoc plugins list Lists the 7 registered deterministic plugins in priority order, including third-party entry-point plugins. Use datadoc plugins show &lt;Name&gt; for detail. Terminal Registry introspection datadoc plugins list", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "7. Step-by-Step Hands-On Tutorial", "u": "cli.html#tutorial", "s": "Follow this sequence using the downloadable demo.csv file to test all features of the DATADOC CLI. Prefer guidance? Start with datadoc wizard demo.csv instead of steps 1–3. Bash Full CLI workflow test sequence # Step 1: Inspect dataset quality and health findings datadoc profile demo.csv --target churn # Step 2: Preview the proposed transformation plan datadoc plan demo.csv --target churn --drop-identifiers # Step 3: Fit the pipeline on training data and save artifact datadoc fit demo.csv \\ --target churn \\ --drop-identifiers \\ --scaling standard \\ --clip-outliers \\ --output artifacts/pipeline.json # Step 4: Transform new validation dataset using saved artifact datadoc transform demo.csv \\ --pipeline artifacts/pipeline.json \\ --output clean_demo.csv # Step 5: Benchmark candidate vs baseline ML performance (with ablation) datadoc evaluate demo.csv \\ --target churn \\ --task classification \\ --estimator tree \\ --ablation # Step 6: Export executable Python wrapper script datadoc export \\ --pipeline artifacts/pipeline.json \\ --output my_pipeline.py # Step 7: Run complete reproducible local run in one command datadoc run demo.csv \\ --target churn \\ --output-dir full-run \\ --evaluate # Step 8: Open interactive Web Dashboard datadoc ui demo.csv", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "8. Master Options Reference Table", "u": "cli.html#flags", "s": "Below is a quick reference matrix of all options across DATADOC CLI commands: Flag / Option Commands Supported Allowed Values Default Description --target profile, plan, fit, evaluate, run Column Name None Declares protected prediction target column --task plan, fit, evaluate, run auto , classification , regression auto Specifies machine learning problem type --drop-identifiers plan, fit, run Boolean Flag False Detects and removes high-cardinality string IDs --identifier-column plan, fit, run Column Name (repeatable) None Forces a column into the identifier role (e.g. PassengerId ) --ignore-column plan, fit, run Column Name (repeatable) None Excludes a column from features entirely --scaling fit, run auto , none , standard , robust auto Selects numeric feature scaling strategy --clip-outliers fit, run Boolean Flag False Clamps numerical outliers to IQR bounds --estimator evaluate linear , tree , both linear Selects model family; both fits linear and tree and keeps the stronger validation score --preset profile, plan, fit, evaluate, run quick , balanced , linear , tree , time , robust None One-word policy bundle for scaling, clipping, threshold, and estimator family --deduplicate fit, run Boolean Flag False Drops duplicate rows from training data at fit time --rare-frequency fit, run Float 0–1 0.0 Groups categories below this frequency into __RARE__ --cyclical fit, run Boolean Flag False Adds sin/cos pairs for datetime parts --no-hour fit, run Boolean Flag False Skips hour extraction even when time data is present --categorical-threshold fit, run Integer 20 Max one-hot width before falling back to frequency encoding --ablation evaluate, run Boolean Flag False Compares full, no-clip, no-scaling, and minimal variants --validate transform Boolean Flag False Runs schema validation and median-shift drift checks --explain profile, plan Boolean Flag False Renders human-readable tables instead of raw JSON --compare profile File Path ( .json ) None Compares against another pr", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "9. Error Recovery &amp; Best Practices", "u": "cli.html#errors", "s": "Holdout Score Warning in Evaluation Evaluation scores are computed via an 80/20 holdout split. Use an external final test set for critical production decisions. Missing Input Columns during Transform If datadoc transform fails with a schema mismatch error, ensure the input dataset contains all feature columns present when datadoc fit was executed.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "CLI Deep Dive & Reference", "u": "cli.html", "s": "Comprehensive DATADOC CLI deep dive: concepts, options, pipeline lifecycle, commands, and step-by-step tutorial. DATADOC provides a local-first, zero-leakage CLI for tabular dataset preparation. Explore parameters, execution mechanics, command breakdowns, and interactive demo testing.", "page": "DATADOC Docs | CLI Deep Dive & Reference", "file": "cli.html"}, {"t": "Make the safe path easier.", "u": "contribute.html", "s": "DATADOC is useful when its decisions are explainable to data scientists and maintainers. Contributions should favor clear contracts, small changes, and tests that prove no leakage. Open GitHub ↗ Copy page", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "Principles", "u": "contribute.html#principles", "s": "01", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "Train-only state", "u": "contribute.html#principles", "s": "Any median, vocabulary, clipping bound, scaler, or selection decision belongs in fit , never in transform . 02", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "Explain decisions", "u": "contribute.html#principles", "s": "Findings and operations need a rationale that a reviewer can read without opening implementation internals. 03", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "Keep extras optional", "u": "contribute.html#principles", "s": "Core profiling and transformation must work offline without AI, UI, or scikit-learn.", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "Transformation contract", "u": "contribute.html#transformer", "s": "A new transformation should fit the project lifecycle. This example is intentionally small; production code should also define its schema and serialization behavior. Python train-only plugin shape import polars as pl class CenterAmount: name = \"center_amount\" def analyze(self, df, context): return {\"code\": \"CUSTOM_FINDING\", \"message\": \"Explain the finding\"} def fit(self, train_df, context): return {\"center\": train_df[\"amount\"].median()} def transform(self, df, fitted_state, context): center = fitted_state[\"center\"] return df.with_columns( (pl.col(\"amount\") - center).alias(\"amount_centered\") ) def validate(self, input_df, output_df, fitted_state): return {\"valid\": \"amount_centered\" in output_df.columns} Do not add arbitrary code execution. AI may suggest a constrained operation, but registered code and deterministic validation must control what runs.", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "Tests you should add", "u": "contribute.html#tests", "s": "Test Question it answers Unit Does the transformation handle nulls, empty data, binary values, and invalid dates? Leakage Can validation values change medians, vocabularies, bounds, or feature selection? Round trip Does save/load produce the same schema and values? CLI Do paths, extensions, and error messages work from a clean command? UI Can two sessions remain independent and do invalid orders fail? Terminal before opening a PR python -m pytest -q python -m ruff check datadoc tests python -m ruff format --check datadoc tests python -m compileall -q datadoc", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "Pull request workflow", "u": "contribute.html#pull", "s": "Fork the repository and create a focused branch. Explain the user problem and the behavior change. Update docs and examples when a public command changes. Add tests before asking for review. Run the local checks and describe any known boundaries. Keep generated datasets, secrets, build directories, and local artifacts out of the commit. Git small, reviewable change git switch -c feat/safer-datetime-transform git add datadoc tests docs git commit -m \"feat: make datetime transform safer\" git push -u origin feat/safer-datetime-transform", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "Contributing", "u": "contribute.html", "s": "Contribute safe transformations, tests, docs, and UI improvements to DATADOC. DATADOC is useful when its decisions are explainable to data scientists and maintainers. Contributions should favor clear contracts, small changes, and tests that prove no leakage.", "page": "DATADOC Docs | Contributing", "file": "contribute.html"}, {"t": "A pipeline that can explain itself.", "u": "how-it-works.html", "s": "DATADOC separates observation, decision, learning, and application. That separation is the product: users can see what will happen, inspect the learned state, and apply it consistently later. Read-only profile first Train-only fit Versioned JSON Follow the full pipeline → Copy page", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "Profile: observe the dataset", "u": "how-it-works.html#profile", "s": "Profiling is a factual pass. It does not impute, encode, scale, clip, or drop your columns. It records enough context to make the next decision inspectable. SCHEMA", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "Types and fingerprint", "u": "how-it-works.html#profile", "s": "Column names, Polars dtypes, row/column counts, and a stable schema fingerprint. QUALITY", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "Findings", "u": "how-it-works.html#profile", "s": "Nulls, duplicates, constants, infinite values, mixed types, and unsupported text warnings. ROLES", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "Confidence + rationale", "u": "how-it-works.html#profile", "s": "Target, numeric, categorical, datetime, identifier, text, ignored, and constant roles. Terminal read-only datadoc profile data.csv \\ --target churn \\ --output profile.json Identifier decisions are not guesses. A numeric column is not an ID just because every value is unique. DATADOC combines names and values, reports confidence, and only drops identifiers when drop_identifiers is explicitly enabled.", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "Plan: review proposed work", "u": "how-it-works.html#plan", "s": "A plan converts findings into ordered operations and reasons. It is safe to show to a teammate or include in a pull request before fitting anything. Finding Default operation Policy Numeric missing values Training median + indicator Fit only on training rows. Categorical values Training vocabulary + unseen-safe encoding High cardinality is reported, not silently deleted. Datetime strings Calendar features if parse confidence passes Preserve parse warnings. Outliers No clipping by default Enable IQR clipping deliberately. Identifiers Retain by default Drop only by explicit policy. JSON shape plan.json { \"operations\": [ {\"operation\": \"numeric_imputation\", \"column\": \"age\", \"reason\": \"Median learned from training data.\"} ], \"findings\": [], \"protected_columns\": [\"churn\"] }", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "Fit and transform: learn once, apply many times", "u": "how-it-works.html#fit", "s": "fit learns state. transform consumes state. That boundary is the rule that prevents test-set leakage. A Training rows Calculate medians, vocabularies, bounds, and scaling centers. B pipeline.json Serialize configuration, input schema, output schema, and fitted state. C New rows Validate compatibility and apply exactly the saved state. Python SDK lifecycle pipeline = DataDocPipeline(config) pipeline.fit(train_df) # learns state validation = pipeline.transform(validation_df) # applies state pipeline.save(\"pipeline.json\") Target columns are protected. If you declare target=\"churn\" , DATADOC does not impute, encode, scale, clip, or drop it as a feature. The transformed frame keeps the target so your code can separate labels explicitly.", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "Leakage safety in plain language", "u": "how-it-works.html#leakage", "s": "Leakage happens when a model gets information it would not have at prediction time. A common example is calculating an imputation median from train and test rows together. Risky pattern Safe pattern Avoid test data influences fit all_rows = pl.concat([train, test]) median = all_rows[\"income\"].median() train = train.with_columns(pl.col(\"income\").fill_null(median)) test = test.with_columns(pl.col(\"income\").fill_null(median)) Use fit state is frozen pipeline = DataDocPipeline( PipelineConfig(scaling=\"none\") ).fit(train) test_features = pipeline.transform(test) Evaluation is evidence, not a guarantee. DATADOC compares a baseline and candidate under a declared split. It can report “no improvement found,” which is often the correct conclusion.", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "How It Works", "u": "how-it-works.html", "s": "How DATADOC profiles, plans, fits, transforms, and evaluates tabular data. DATADOC separates observation, decision, learning, and application. That separation is the product: users can see what will happen, inspect the learned state, and apply it consistently later.", "page": "DATADOC Docs | How It Works", "file": "how-it-works.html"}, {"t": "Prepare data once. Reuse it safely.", "u": "index.html", "s": "DATADOC profiles tabular data, proposes explainable transformations, fits them on training data only, and gives you a reusable artifact for validation, test, and inference. v0.5.0 Python 3.10–3.12 CSV + Parquet Offline core Get started → Run quickstart Copy page FIRST COMMAND", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Inspect before you change.", "u": "index.html", "s": "Start with a read-only profile. Every later decision can be reviewed, overridden, and reproduced. datadoc profile train.csv --target churn profile → plan → fit frozen artifact → transform → evaluate", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Quickstart", "u": "index.html#quickstart", "s": "Use a training file with an optional target. DATADOC writes JSON and Parquet artifacts without requiring a notebook. bash Python PowerShell Terminal train → transform → evaluate pip install datadoc-cli datadoc profile train.csv --target churn --output profile.json datadoc plan train.csv --target churn --task classification --output plan.json datadoc fit train.csv --target churn --output artifacts/churn-pipeline.json datadoc transform validation.csv \\ --pipeline artifacts/churn-pipeline.json \\ --output validation-features.parquet Python same artifact, any process import polars as pl from datadoc import DataDocPipeline, PipelineConfig train = pl.read_csv(\"train.csv\") validation = pl.read_csv(\"validation.csv\") pipeline = DataDocPipeline( PipelineConfig(target=\"churn\", task=\"classification\") ).fit(train) features = pipeline.transform(validation) pipeline.save(\"artifacts/churn-pipeline.json\") PowerShell Windows-friendly python -m pip install datadoc-cli datadoc fit .\\train.csv --target churn ` --output .\\artifacts\\churn-pipeline.json datadoc transform .\\validation.csv ` --pipeline .\\artifacts\\churn-pipeline.json ` --output .\\validation-features.parquet What happens here? fit learns medians, category vocabularies, datetime rules, and optional scaling statistics from train.csv . transform reuses those frozen values; it never learns from validation rows.", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "One mental model", "u": "index.html#workflow", "s": "Every DATADOC interface maps to the same six-step workflow. If you understand this flow, you understand the CLI, SDK, and web UI. 01 Profile Find nulls, duplicates, constants, IDs, roles, and schema risks. 02 Plan Review proposed operations before any data is modified. 03 Fit Learn train-only statistics and save a versioned artifact. 04 Transform Apply the same output schema to validation, test, or new data. 05 Evaluate Compare a candidate against a baseline for a declared task. 06 Ship Export code, lineage, and artifacts that another person can inspect.", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "What DATADOC handles", "u": "index.html#capabilities", "s": "01 / PROFILE", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Data-quality findings", "u": "index.html#capabilities", "s": "Missingness, duplicates, constants, cardinality, invalid values, datetime confidence, and suspected leakage. 02 / TRANSFORM", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Safe preparation", "u": "index.html#capabilities", "s": "Train-fitted imputation, missing indicators, category encoding, datetime features, optional clipping, and scaling. 03 / ARTIFACT", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Portable state", "u": "index.html#capabilities", "s": "Save the input contract, output schema, configuration, plan, fitted values, and artifact version as JSON. 04 / EVALUATE", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Measured outcomes", "u": "index.html#capabilities", "s": "Use classification or regression baselines with stratified, ordered, or group-aware validation. 05 / UI", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Local workspace", "u": "index.html#capabilities", "s": "Review findings, approve a plan, preview output, inspect lineage, and download artifacts from the local dashboard (Ctrl+K palette). 06 / OPEN SOURCE", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Inspectable by default", "u": "index.html#capabilities", "s": "No cloud dependency for the core. Optional AI is advisory and cannot execute generated code.", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Choose your path", "u": "index.html#paths", "s": "CLI users Python users Dashboard users Best for repeatable batch jobs and CI. Read the CLI reference → Best for notebooks, services, and custom orchestration. Read the Python SDK → Best for exploring a dataset locally with visual feedback. Read the UI guide →", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "What you get back", "u": "index.html#outputs", "s": "Output Purpose When it appears profile.json Facts, roles, findings, and schema fingerprint. profile or run plan.json Explainable operations and rationales. plan or run pipeline.json Frozen train-only transformation state. fit or run evaluation.json Baseline, candidate, metric, split, and warnings. evaluate or run --evaluate manifest.json Lineage: input fingerprint, config, output schema, and artifact links. run", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "When something goes wrong", "u": "index.html#errors", "s": "Target errors If the target is missing, null, or accidentally transformed, stop and fix the declaration. Use --target column_name ; DATADOC never guesses a supervised target. Schema errors If transform reports missing columns or incompatible types, compare the new file with the artifact’s input_schema . Do not silently rename columns in production. Unexpected score changes Check the evaluation split, target leakage findings, estimator family, and whether the selected pipeline actually beat the baseline. “No improvement found” is a valid result.", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "Overview", "u": "index.html", "s": "DATADOC documentation: leakage-safe tabular data preparation with CLI, Python SDK, and local web UI. DATADOC profiles tabular data, proposes explainable transformations, fits them on training data only, and gives you a reusable artifact for validation, test, and inference.", "page": "DATADOC Docs | Overview", "file": "index.html"}, {"t": "MIT license.", "u": "license.html", "s": "DATADOC is open source and intended to be inspectable, forkable, and useful to data scientists and ML engineers. View repository ↗ Copy page", "page": "DATADOC Docs | License", "file": "license.html"}, {"t": "License text", "u": "license.html#mit", "s": "MIT Copyright (c) 2026 DATADOC Contributors Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the \"Software\"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions: The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software. THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.", "page": "DATADOC Docs | License", "file": "license.html"}, {"t": "License", "u": "license.html", "s": "DATADOC is released under the MIT license. DATADOC is open source and intended to be inspectable, forkable, and useful to data scientists and ML engineers.", "page": "DATADOC Docs | License", "file": "license.html"}, {"t": "From raw table to reusable artifact.", "u": "pipeline.html", "s": "This is the canonical DATADOC path. Each stage has a clear input, output, and failure mode so a developer can move from exploration to a repeatable ML preparation job. profile → plan → fit → transform optional evaluate JSON artifact See every CLI option → Copy page", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "1. Profile the source", "u": "pipeline.html#profile", "s": "Start with facts, not mutations. Profiles are useful in code review because they preserve the evidence behind a transformation decision. Terminal profile.json is optional datadoc profile data.csv \\ --target churn \\ --output profile.json Profile field Why it matters roles Explains whether a column is a target, feature, datetime, identifier, text, or constant. findings Surfaces all-null fields, duplicates, infinite values, unsupported text, and leakage clues. schema_fingerprint Lets a run record which input contract produced an artifact.", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "2. Create and review a plan", "u": "pipeline.html#plan", "s": "Plans are deterministic and do not modify data. In a team, save the plan beside the experiment configuration so reviewers can see why a column changed. Terminal plan.json datadoc plan data.csv \\ --target churn \\ --task classification \\ --output plan.json Destructive behavior is explicit. Outlier clipping is opt-in. Identifier dropping requires --drop-identifiers . High-cardinality fields produce findings and are not silently discarded.", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "3. Fit only on training data", "u": "pipeline.html#fit", "s": "The fit step learns reusable statistics and writes a JSON artifact. Use a real training split here when a model will be evaluated later. Terminal train-only state datadoc fit train.csv \\ --target churn \\ --task classification \\ --scaling auto \\ --output artifacts/churn-pipeline.json", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "What is learned?", "u": "pipeline.html#fit", "s": "Numeric medians and missingness-indicator decisions. Categorical vocabularies or frequency maps. Datetime parsing and stable calendar feature rules. Optional IQR clipping bounds. Optional standard or robust scaling centers and spreads.", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "4. Transform validation, test, or inference", "u": "pipeline.html#transform", "s": "Transform validates the artifact’s input contract and applies the saved state. It handles unseen categories without changing the output schema. Terminal same artifact, different rows datadoc transform validation.csv \\ --pipeline artifacts/churn-pipeline.json \\ --output validation-features.parquet datadoc transform new_customers.csv \\ --pipeline artifacts/churn-pipeline.json \\ --output new-customer-features.csv Do not refit for inference. Loading a new file into a new pipeline and calling fit changes the learned state. Use DataDocPipeline.load(...).transform(...) or the CLI artifact path.", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "5. Understand pipeline.json", "u": "pipeline.html#artifact", "s": "The artifact is intentionally inspectable. It is JSON rather than a hidden binary model object. JSON abridged artifact { \"artifact_version\": 2, \"datadoc_version\": \"0.5.0\", \"config\": {\"target\": \"churn\", \"task\": \"classification\"}, \"input_schema\": {\"age\": \"Int64\", \"plan\": \"String\"}, \"output_schema\": {\"age\": \"Float64\", \"plan__pro\": \"UInt8\"}, \"provenance\": {\"schema_fingerprint\": \"74cfba9cbc7242be\", \"rows\": 500, \"deduplicated_rows\": 0}, \"state\": { \"numeric\": {\"age\": {\"median\": 35.0}}, \"categorical\": {\"plan\": {\"kind\": \"one_hot\"}} } } Artifact loading accepts v1 and v2 and rejects anything else; transform rejects missing required source columns. Keep the artifact with the model run that consumed it.", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "6. Evaluate the preparation choice", "u": "pipeline.html#evaluate", "s": "Evaluation requires the ML extra and a declared target. DATADOC compares a minimal baseline with the configured candidate using cross-validation and a holdout. Terminal classification example python -m pip install \"datadoc-cli[ml]\" datadoc evaluate train.csv \\ --target churn \\ --task classification \\ --estimator linear \\ --output evaluation.json Task Primary metric Default split Classification Balanced accuracy Stratified CV + holdout Regression RMSE K-fold CV + holdout Time-aware Same metric Ordered split with --time-column Grouped Same metric Group-aware split with --group-column Read the whole report. A positive score difference is not enough. Check the split strategy, estimator family, feature count, warnings, and whether an untouched external test set agrees.", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "7. Use the guided run", "u": "pipeline.html#run", "s": "run is convenient for local experiments. It creates a profile, plan, fitted artifact, transformed Parquet, and manifest in one directory. Terminal runs/churn-v1/ datadoc run data.csv \\ --target churn \\ --task classification \\ --output-dir runs/churn-v1 \\ --evaluate Use fit and transform separately when you have a deliberately reserved final test set or a production inference boundary.", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "Pipeline Guide", "u": "pipeline.html", "s": "Complete DATADOC pipeline guide for profile, plan, fit, transform, and evaluate. This is the canonical DATADOC path. Each stage has a clear input, output, and failure mode so a developer can move from exploration to a repeatable ML preparation job.", "page": "DATADOC Docs | Pipeline Guide", "file": "pipeline.html"}, {"t": "Make every transformation accountable.", "u": "production.html", "s": "Production readiness is more than a successful transform. Keep the artifact, configuration, schema fingerprint, evaluation report, and test evidence together so another developer can reproduce the decision. artifact + lineage CI matrix PyPI 0.5.0 Ship checklist → Copy page", "page": "DATADOC Docs | Production", "file": "production.html"}, {"t": "1. Define the data contract", "u": "production.html#contract", "s": "Contract Check Failure action Input schema Required columns, types, and target are present. Stop and inspect the artifact schema. Role policy Identifiers, protected columns, and time/group columns are deliberate. Update configuration; do not silently drop data. Split policy Classification is stratified; time/group data uses matching split strategy. Rerun evaluation with explicit columns. Output schema Feature names and order stay stable for inference. Reject the artifact and investigate drift.", "page": "DATADOC Docs | Production", "file": "production.html"}, {"t": "2. Ship the artifact, not a notebook cell", "u": "production.html#ship", "s": "Terminal recommended run bundle datadoc run data.csv \\ --target churn \\ --task classification \\ --output-dir runs/churn-v1 \\ --evaluate # inspect before deployment Get-ChildItem runs/churn-v1 # PowerShell ls runs/churn-v1 # Unix Keep at minimum: pipeline.json , manifest.json , the approved plan.json , the evaluation report, and the package version. The JSON artifact is the source of truth for transform behavior. Do not upload secrets or raw production data. Artifacts can contain category values and fitted statistics. Treat them as data assets; review privacy and retention requirements before publishing them.", "page": "DATADOC Docs | Production", "file": "production.html"}, {"t": "3. CI gates for contributors", "u": "production.html#ci", "s": "Terminal local equivalent of CI python -m pytest -q python -m ruff check datadoc tests python -m ruff format --check datadoc tests python -m compileall -q datadoc uv lock --check uv build cd web npm ci npm run build The repository matrix covers Python 3.10–3.12, multiple operating systems, package building, and frontend compilation. Open-source rule Optional dependencies remain optional. A user who only wants local profiling should not need an API key, scikit-learn, or a web server.", "page": "DATADOC Docs | Production", "file": "production.html"}, {"t": "4. Release to PyPI", "u": "production.html#release", "s": "Version 0.5.0 is the current release. Before upload, commit the source and docs, push to GitHub, wait for CI, tag the same version, and validate the artifacts. Terminal maintainer flow python -m pip install --upgrade twine python -m twine check dist/* python -m twine upload dist/datadoc_cli-0.5.0* Never put a PyPI token in source control. Use trusted publishing or a short-lived token stored in the environment. See RELEASE_CHECKLIST.md in the repository for the complete sequence.", "page": "DATADOC Docs | Production", "file": "production.html"}, {"t": "5. What to monitor after release", "u": "production.html#observability", "s": "Input schema drift and unseen categories. Null and missingness rates compared with the profile baseline. Output feature count and names. Model performance on a separately governed evaluation set. Artifact version and package version used in every job.", "page": "DATADOC Docs | Production", "file": "production.html"}, {"t": "Production", "u": "production.html", "s": "DATADOC production, artifact, CI, release, and PyPI guidance. Production readiness is more than a successful transform. Keep the artifact, configuration, schema fingerprint, evaluation report, and test evidence together so another developer can reproduce the decision.", "page": "DATADOC Docs | Production", "file": "production.html"}, {"t": "Build the pipeline into your application.", "u": "sdk.html", "s": "The SDK exposes the same safe lifecycle as the CLI, but returns typed Python objects and Polars DataFrames for notebooks, services, and scheduled jobs. from datadoc import DataDocPipeline Polars DataFrame JSON save/load Copy the quickstart → Copy page", "page": "DATADOC Docs | Python SDK", "file": "sdk.html"}, {"t": "1. Install", "u": "sdk.html#install", "s": "Terminal core + optional ML python -m pip install datadoc-cli python -m pip install \"datadoc-cli[ml]\" The core SDK does not import scikit-learn until evaluate is called. This keeps preparation usable offline and keeps optional dependencies explicit.", "page": "DATADOC Docs | Python SDK", "file": "sdk.html"}, {"t": "2. Quickstart", "u": "sdk.html#quickstart", "s": "Python profile → plan → fit → transform import polars as pl from datadoc import DataDocPipeline, PipelineConfig train = pl.read_csv(\"train.csv\") validation = pl.read_csv(\"validation.csv\") config = PipelineConfig( target=\"churn\", task=\"classification\", scaling=\"standard\", clip_outliers=False, random_seed=42, ) pipeline = DataDocPipeline(config) profile = pipeline.profile(train) plan = pipeline.plan(train) pipeline.fit(train) features = pipeline.transform(validation) pipeline.save(\"artifacts/churn-pipeline.json\") print(profile.to_dict()) print(plan.to_dict()) print(features.shape) The target stays available. DATADOC protects the target from feature operations but leaves it in the returned frame. Separate X and y in the model layer when you are ready.", "page": "DATADOC Docs | Python SDK", "file": "sdk.html"}, {"t": "3. Configure deliberate behavior", "u": "sdk.html#config", "s": "Python common controls config = PipelineConfig( target=\"churn\", task=\"classification\", # or regression scaling=\"robust\", # none, standard, robust, auto drop_identifiers=False, deduplicate=False, clip_outliers=False, rare_category_min_frequency=0.0, # e.g. 0.02 groups rare into __RARE__ datetime_cyclical=False, datetime_extract_hour=True, categorical_threshold=20, estimator_family=\"linear\", # linear | tree | both time_column=None, group_column=None, strict_schema=True, random_seed=42, ) Config Default Use it when target None You have a supervised label to protect. scaling auto Linear or distance-based models need normalized features. drop_identifiers False You have reviewed the profile and want explicit removal. strict_schema True You want inference failures to be visible rather than silently coerced.", "page": "DATADOC Docs | Python SDK", "file": "sdk.html"}, {"t": "4. Save and load across processes", "u": "sdk.html#serialization", "s": "Python artifact boundary pipeline.save(\"artifacts/pipeline.json\") loaded = DataDocPipeline.load(\"artifacts/pipeline.json\") features = loaded.transform(new_rows) Artifacts (v2) include the configuration, input schema, output schema, plan, profile, train provenance (schema fingerprint, row counts, deduplicated rows, package version), and fitted state. Loading accepts v1 and v2 and fails only on unsupported versions. Extra helpers: explain_plan(df) , drift_report(df) , evaluate_ablation(df) , profile_to_html(df) for notebooks, and export_sklearn_artifact(path) for joblib portability.", "page": "DATADOC Docs | Python SDK", "file": "sdk.html"}, {"t": "5. Evaluate from Python", "u": "sdk.html#evaluate", "s": "Python requires datadoc-cli[ml] report = DataDocPipeline( PipelineConfig( target=\"churn\", task=\"classification\", estimator_family=\"linear\", time_column=None, group_column=None, ) ).evaluate(train, target=\"churn\") print(report.to_dict()) The report names the task, metric, estimator family, split strategy, baseline score, selected score, improvement, feature count, selected pipeline, and warnings. Use an external final test set. Built-in evaluation gives structured evidence on the supplied data. Keep the final production test set untouched until you have selected the preparation strategy.", "page": "DATADOC Docs | Python SDK", "file": "sdk.html"}, {"t": "6. Handle SDK errors", "u": "sdk.html#errors", "s": "Python actionable failure from datadoc import DataDocPipeline, PipelineConfig from datadoc.core.pipeline import DataDocError try: pipeline = DataDocPipeline( PipelineConfig(target=\"churn\") ).fit(train) features = pipeline.transform(inference) except DataDocError as error: print(f\"DATADOC input contract failed: {error}\") Missing target: pass the correct target name or use an unsupervised preparation flow. Missing source columns: compare the input file with pipeline.input_schema_ . Unseen category: safe by default; the output schema remains stable. Unsupported file: read it into Polars, then pass the DataFrame to the SDK.", "page": "DATADOC Docs | Python SDK", "file": "sdk.html"}, {"t": "Python SDK", "u": "sdk.html", "s": "DATADOC Python SDK guide with fitting, serialization, evaluation, and errors. The SDK exposes the same safe lifecycle as the CLI, but returns typed Python objects and Polars DataFrames for notebooks, services, and scheduled jobs.", "page": "DATADOC Docs | Python SDK", "file": "sdk.html"}, {"t": "Install the core. Add what you need.", "u": "setup.html", "s": "The default package is local and offline. Model evaluation, the dashboard, AI planning, and contributor tools are opt-in extras so a data-cleaning script does not install a full platform. Install now → Copy page", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "1. Install DATADOC", "u": "setup.html#install", "s": "Use Python 3.10, 3.11, or 3.12. Create a virtual environment for each project so the pipeline version is explicit. Terminal recommended python -m venv .venv python -m pip install --upgrade pip python -m pip install datadoc-cli Or with uv : uv fast environment setup uv venv uv pip install datadoc-cli", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "2. Choose optional extras", "u": "setup.html#extras", "s": "Extra Install Adds Core datadoc-cli Profile, plan, fit, transform, export, CSV, and Parquet. ML datadoc-cli[ml] scikit-learn baselines and evaluation reports. UI datadoc-cli[ui] FastAPI, Uvicorn, and multipart support for the local dashboard. AI datadoc-cli[ai] Optional advisory planning through LiteLLM. It never executes code. Dev datadoc-cli[dev] Pytest, Ruff, build tooling, and scikit-learn for contributors. Terminal common project setup python -m pip install \"datadoc-cli[ml,ui]\"", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "3. Verify the install", "u": "setup.html#verify", "s": "Check that the command is available and run a read-only profile on your own data. Terminal no data is modified datadoc --help datadoc version datadoc profile data.csv Expected behavior The profile command prints JSON-like output containing the schema, null counts, cardinality, roles, findings, duplicate count, and schema fingerprint. It does not write a cleaned dataset.", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "4. Input and output formats", "u": "setup.html#inputs", "s": "CSV", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "Comma-separated files", "u": "setup.html#inputs", "s": "Read with Polars schema inference. Use a stable header and consistent types between train and inference. PARQUET", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "Typed columnar files", "u": "setup.html#inputs", "s": "Preserves types more reliably and is recommended for transformed feature outputs. LIMIT", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "Tabular only", "u": "setup.html#inputs", "s": "Free text, image, joins, geospatial, and distributed workflows are reported as boundaries rather than guessed.", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "5. Troubleshooting", "u": "setup.html#troubleshoot", "s": "“Only CSV and Parquet files are supported.” Convert spreadsheets or JSON upstream, or export them as CSV/Parquet with an explicit schema. “Evaluation requires optional ML dependencies.” Install python -m pip install \"datadoc-cli[ml]\" in the same environment that owns the datadoc command. Command shows an old version Activate the intended virtual environment, reinstall the package, and check where datadoc on Windows or which datadoc on macOS/Linux. Diagnostics Windows + Unix python -c \"import datadoc; print(datadoc.__file__)\" where datadoc # Windows which datadoc # macOS / Linux", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "Installation", "u": "setup.html", "s": "Install DATADOC and its optional ML, UI, AI, and developer extras. The default package is local and offline. Model evaluation, the dashboard, AI planning, and contributor tools are opt-in extras so a data-cleaning script does not install a full platform.", "page": "DATADOC Docs | Installation", "file": "setup.html"}, {"t": "A visual desk for the same pipeline.", "u": "ui.html", "s": "The dashboard is a consumer of the CLI/SDK architecture. It helps a person inspect findings, configure policy, review operations, fit a pipeline, preview rows, and export code without introducing a separate data-cleaning engine. localhost only by default session-scoped state React + FastAPI Start locally → Copy page", "page": "DATADOC Docs | Web UI", "file": "ui.html"}, {"t": "1. Start the local dashboard", "u": "ui.html#start", "s": "Terminal backend serves built frontend python -m pip install \"datadoc-cli[ui]\" datadoc ui data.csv --port 8000 The command initializes a local session, starts Uvicorn on 127.0.0.1 , and opens the browser. The frontend build is served from web/dist when it exists. Development API base When running Vite separately, set VITE_DATADOC_API_URL=http://127.0.0.1:8000/api so the browser talks to the backend instead of the Vite port.", "page": "DATADOC Docs | Web UI", "file": "ui.html"}, {"t": "2. Use the workspace", "u": "ui.html#workspace", "s": "01 Profile Review roles, findings, null counts, and cardinality. The loaded file name and shape appear in the header. 02 Settings Declare target/task/scaling; opt into identifier dropping, deduplication, IQR clipping, cyclical datetime, or rare-category grouping only after review. 03 Plan Inspect each operation and rationale before fitting. 04 Fit Create session-scoped state, then preview the output schema, preview rows, and lineage panel. 05 Export Download transformed CSV or the executable Python wrapper ( python pipeline.py in.csv out.csv ). UI is not a replacement for a deployment split. For model performance claims, fit on train data and transform validation/test with the saved artifact. The UI’s loaded file is primarily an exploratory local workspace.", "page": "DATADOC Docs | Web UI", "file": "ui.html"}, {"t": "3. Command palette and lineage", "u": "ui.html#palette", "s": "Press Ctrl+K (or Cmd+K ) anywhere in the dashboard to fuzzy-search actions: go to views, build a plan, fit, refresh, download CSV, or load the export. After fitting, the sidebar shows a lineage panel with train provenance (schema fingerprint, row counts, deduplicated rows) and input/output column counts. Full detail is available at GET /api/pipeline/lineage , and drift checks at GET /api/pipeline/drift .", "page": "DATADOC Docs | Web UI", "file": "ui.html"}, {"t": "4. Develop the frontend", "u": "ui.html#dev", "s": "PowerShell from web/ npm ci $env:VITE_DATADOC_API_URL = \"http://127.0.0.1:8000/api\" npm run dev # production build npm run build The entry point is web/src/App.jsx . It uses the backend metadata, profile, plan, fit, preview, lineage, drift, and export endpoints — every number on screen comes from a live API response, never bundled mock data. Keep data behavior in datadoc/core/pipeline.py ; keep UI state and presentation in React. Rebuild with npm run build so web/dist matches the source before running datadoc ui .", "page": "DATADOC Docs | Web UI", "file": "ui.html"}, {"t": "5. Security and sessions", "u": "ui.html#security", "s": "Concern DATADOC behavior Developer responsibility Network binding Localhost by default. Do not expose Uvicorn publicly without an auth/reverse-proxy plan. CORS Configured local origins, no wildcard credentials. Set DATADOC_UI_ORIGINS deliberately for development. State Session-scoped pipeline/profile/plan objects. Use a durable job store before multi-user deployment. AI Optional; generated code is never executed by the pipeline. Minimize metadata and validate any advisory plan. JavaScript session header const SESSION_HEADERS = { \"X-DATADOC-SESSION\": \"local\", }; await axios.get(\"/api/pipeline/preview\", { headers: SESSION_HEADERS, });", "page": "DATADOC Docs | Web UI", "file": "ui.html"}, {"t": "6. UI error recovery", "u": "ui.html#errors", "s": "“Fit a pipeline before preview.” Click Build plan first if you want to review, then click Fit pipeline before preview, lineage, drift, or code export. “Unable to connect to the local DATADOC server.” Start datadoc ui data.csv , verify the port, and set VITE_DATADOC_API_URL when using a separate frontend dev server.", "page": "DATADOC Docs | Web UI", "file": "ui.html"}, {"t": "Web UI", "u": "ui.html", "s": "DATADOC local web UI guide for sessions, pipeline actions, frontend development, and troubleshooting. The dashboard is a consumer of the CLI/SDK architecture. It helps a person inspect findings, configure policy, review operations, fit a pipeline, preview rows, and export code without introducing a separate data-cleaning engine.", "page": "DATADOC Docs | Web UI", "file": "ui.html"}];

  function currentPage() {
    const name = window.location.pathname.split('/').pop() || 'index.html';
    const clean = name.split('?')[0].split('#')[0];
    return clean === '' ? 'index.html' : clean;
  }

  function setActiveNavigation() {
    const page = currentPage();
    $$('[data-page-link]').forEach((link) => {
      link.classList.toggle('active', link.getAttribute('href') === page);
    });
  }

  function setupMobileMenu() {
    const button = $('[data-menu-toggle]');
    const overlay = $('.mobile-overlay');
    if (!button) return;
    const close = () => {
      document.body.classList.remove('menu-open');
      button.setAttribute('aria-expanded', 'false');
    };
    button.addEventListener('click', () => {
      const open = document.body.classList.toggle('menu-open');
      button.setAttribute('aria-expanded', String(open));
    });
    overlay?.addEventListener('click', close);
    $$('.sidebar a').forEach((link) => link.addEventListener('click', close));
    document.addEventListener('keydown', (event) => { if (event.key === 'Escape') close(); });
  }

  function escapeHtml(value) {
    return String(value).replace(/[&<>"']/g, (character) => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;',
    }[character]));
  }

  function escapeRegExp(value) {
    return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function highlightSource(source, language) {
    const keywords = new Set([
      'as', 'async', 'await', 'break', 'case', 'class', 'const', 'continue', 'def', 'default',
      'del', 'elif', 'else', 'export', 'extends', 'finally', 'for', 'from', 'function', 'if',
      'import', 'in', 'interface', 'let', 'new', 'pass', 'return', 'static', 'switch', 'throw',
      'try', 'typeof', 'var', 'while', 'with', 'yield', 'param', 'process', 'begin', 'end',
    ]);
    const constants = new Set(['True', 'False', 'None', 'null', 'undefined', 'true', 'false', 'NaN']);
    const types = new Set(['DataDocPipeline', 'PipelineConfig', 'DataFrame', 'JSON', 'Polars', 'Promise', 'String', 'Number', 'Boolean']);
    const shellLanguages = /terminal|powershell|shell|bash|zsh|git|uv/i.test(language);
    const tokenPattern = /#.*|\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b\d+(?:\.\d+)?\b|--?[A-Za-z][\w-]*|\b[A-Za-z_$][\w$]*\b|[{}[\]();,.:=+\-*/<>!?|&]/gm;
    let output = '';
    let cursor = 0;
    let match;
    while ((match = tokenPattern.exec(source)) !== null) {
      output += escapeHtml(source.slice(cursor, match.index));
      const token = match[0];
      const end = match.index + token.length;
      const before = source[match.index - 1] || '';
      const after = source.slice(end);
      const lineStart = source.lastIndexOf('\n', match.index - 1) + 1;
      const atLineStart = source.slice(lineStart, match.index).trim() === '';
      let tokenClass = '';
      if (token.startsWith('#') || token.startsWith('//') || token.startsWith('/*')) tokenClass = 'tok-comment';
      else if (/^["'`]/.test(token)) tokenClass = /^\s*:/.test(after) ? 'tok-property' : 'tok-string';
      else if (/^\d/.test(token)) tokenClass = 'tok-number';
      else if (/^--?\w/.test(token)) tokenClass = 'tok-flag';
      else if (/^[A-Za-z_$]/.test(token)) {
        if (constants.has(token)) tokenClass = 'tok-constant';
        else if (types.has(token)) tokenClass = 'tok-type';
        else if (keywords.has(token)) tokenClass = 'tok-keyword';
        else if (/^\s*\(/.test(after)) tokenClass = 'tok-function';
        else if (before === '.') tokenClass = 'tok-property';
        else if (shellLanguages && atLineStart) tokenClass = 'tok-command';
      } else if (/^[{}[\]();,.:]$/.test(token)) tokenClass = 'tok-punctuation';
      else tokenClass = 'tok-operator';
      const safeToken = escapeHtml(token);
      output += tokenClass ? `<span class="${tokenClass}">${safeToken}</span>` : safeToken;
      cursor = end;
    }
    return output + escapeHtml(source.slice(cursor));
  }

  function setupSyntaxHighlighting() {
    $$('pre[data-copy] code').forEach((code) => {
      if (code.dataset.highlighted) return;
      const block = code.closest('pre');
      const language = $('.code-caption .lang', block)?.textContent || 'Code';
      code.innerHTML = highlightSource(code.textContent, language);
      code.dataset.highlighted = 'true';
    });
  }

  function setupCopyButtons() {
    $$('pre[data-copy]').forEach((block) => {
      if ($('.copy-button', block)) return;
      const button = document.createElement('button');
      button.className = 'copy-button';
      button.type = 'button';
      button.textContent = 'Copy';
      button.setAttribute('aria-label', 'Copy code to clipboard');
      button.addEventListener('click', async () => {
        const code = $('code', block)?.innerText || block.innerText;
        try {
          await navigator.clipboard.writeText(code.trim());
          button.textContent = 'Copied';
          button.classList.add('copied');
          window.setTimeout(() => {
            button.textContent = 'Copy';
            button.classList.remove('copied');
          }, 1400);
        } catch (error) {
          button.textContent = 'Select';
        }
      });
      block.appendChild(button);
    });
    $('[data-copy-page]')?.addEventListener('click', async (event) => {
      const button = event.currentTarget;
      const text = $('.main-content')?.innerText || document.body.innerText;
      try {
        await navigator.clipboard.writeText(text.trim());
        button.textContent = 'Page copied';
        window.setTimeout(() => { button.textContent = 'Copy page'; }, 1400);
      } catch (error) {
        button.textContent = 'Select page text';
      }
    });
  }

  function setupTabs() {
    $$('.tabs').forEach((tabs) => {
      const buttons = $$('.tab-button', tabs);
      const panels = $$('.tab-panel', tabs);
      buttons.forEach((button) => {
        button.addEventListener('click', () => {
          const name = button.dataset.tab;
          buttons.forEach((item) => item.classList.toggle('active', item === button));
          panels.forEach((panel) => panel.classList.toggle('active', panel.dataset.panel === name));
        });
      });
    });
  }

  // ---------- Full-text search ----------
  function tokenize(query) {
    return query.toLowerCase().split(/[\s,;:.!?()[\]{}"'`]+/).map((t) => t.trim()).filter((t) => t.length >= 2);
  }

  function buildSnippet(text, terms, phrase) {
    const source = text || '';
    const lower = source.toLowerCase();
    let first = -1;
    if (phrase && phrase.length >= 3) first = lower.indexOf(phrase);
    if (first < 0) {
      for (const term of terms) {
        const i = lower.indexOf(term);
        if (i >= 0 && (first < 0 || i < first)) first = i;
      }
    }
    if (first < 0) return escapeHtml(source.slice(0, 160)) + (source.length > 160 ? '…' : '');
    const start = Math.max(0, first - 70);
    const end = Math.min(source.length, first + 110);
    let window = source.slice(start, end);
    const pattern = new RegExp(`(${escapeRegExp(phrase)}|${terms.map(escapeRegExp).join('|')})`, 'gi');
    window = escapeHtml(window).replace(pattern, '<mark>$1</mark>');
    return (start > 0 ? '…' : '') + window + (end < source.length ? '…' : '');
  }

  function searchDocs(query) {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return [];
    const terms = tokenize(normalized);
    if (!terms.length) return [];
    const phrase = normalized.replace(/\s+/g, ' ').trim();
    const scored = [];
    for (const entry of docsIndex) {
      const title = entry.t || '';
      const body = entry.s || '';
      const page = entry.page || '';
      const hay = `${title} ${body} ${page} ${entry.u}`.toLowerCase();
      // AND semantics: every term must appear somewhere (title, body, page, url)
      const allPresent = terms.every((term) => hay.includes(term));
      if (!allPresent) continue;
      let score = 0;
      const titleLower = title.toLowerCase();
      const bodyLower = body.toLowerCase();
      if (phrase.length >= 3 && hay.includes(phrase)) score += 60;
      for (const term of terms) {
        if (titleLower.includes(term)) score += 25;
        if (page.toLowerCase().includes(term)) score += 4;
        const occurrences = bodyLower.split(term).length - 1;
        score += Math.min(occurrences, 5) * 3;
        if (titleLower.startsWith(term)) score += 8;
      }
      // Prefer heading matches over generic page entries and shorter anchors
      if (entry.u.includes('#')) score += 5;
      scored.push({ entry, score });
    }
    scored.sort((a, b) => b.score - a.score);
    return scored.slice(0, 14).map(({ entry, score }) => ({
      title: entry.t,
      url: entry.u,
      page: entry.page,
      snippet: buildSnippet(entry.s || entry.t, terms, phrase),
      score,
    }));
  }

  function setupSearch() {
    const input = $('[data-search-input]');
    const results = $('.search-results');
    if (!input || !results) return;
    let selected = -1;
    let current = [];

    const render = (query) => {
      const normalized = query.trim();
      if (!normalized) {
        results.classList.remove('open');
        results.innerHTML = '';
        current = [];
        selected = -1;
        return;
      }
      current = searchDocs(normalized);
      selected = current.length ? 0 : -1;
      if (!current.length) {
        results.innerHTML = '<div class="no-results">No matching docs. Try “pipeline”, “evaluate”, “transform”, “leakage”, or “session”.</div>';
      } else {
        const pages = new Set(current.map((r) => r.url.split('#')[0])).size;
        results.innerHTML = `<div class="search-meta">${current.length} result${current.length === 1 ? '' : 's'} · ${pages} page${pages === 1 ? '' : 's'} · full-text</div>` + current.map((r, i) => {
          const sep = r.url.includes('#') ? '' : ' · top of page';
          const parts = r.url.split('#');
          const href = parts.length > 1
            ? `${parts[0]}?q=${encodeURIComponent(normalized)}#${parts[1]}`
            : `${parts[0]}?q=${encodeURIComponent(normalized)}`;
          return `<a class="search-result${i === selected ? ' selected' : ''}" href="${escapeHtml(href)}" data-index="${i}"><strong>${escapeHtml(r.title)}</strong><span class="result-page">${escapeHtml(r.page)}${sep}</span><span class="result-snippet">${r.snippet}</span></a>`;
        }).join('');
      }
      results.classList.add('open');
    };

    // Preserve deep-link highlight (?q=) when navigating to anchor-only URLs
    results.addEventListener('click', (event) => {
      const link = event.target.closest('a.search-result');
      if (!link) return;
      results.classList.remove('open');
    });

    input.addEventListener('input', () => render(input.value));
    input.addEventListener('focus', () => { if (input.value) render(input.value); });
    input.addEventListener('keydown', (event) => {
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        if (!current.length) return;
        event.preventDefault();
        selected = event.key === 'ArrowDown'
          ? (selected + 1) % current.length
          : (selected - 1 + current.length) % current.length;
        $$('.search-result', results).forEach((el, i) => el.classList.toggle('selected', i === selected));
        $('.search-result.selected', results)?.scrollIntoView({ block: 'nearest' });
      } else if (event.key === 'Enter' && selected >= 0 && current[selected]) {
        event.preventDefault();
        const target = current[selected];
        const parts = target.url.split('#');
        const href = parts.length > 1
          ? `${parts[0]}?q=${encodeURIComponent(input.value.trim())}#${parts[1]}`
          : `${parts[0]}?q=${encodeURIComponent(input.value.trim())}`;
        window.location.href = href;
      }
    });
    document.addEventListener('keydown', (event) => {
      if (event.key === '/' && document.activeElement !== input && !/INPUT|TEXTAREA/.test(document.activeElement?.tagName || '')) {
        event.preventDefault();
        input.focus();
      }
      if (event.key === 'Escape') {
        results.classList.remove('open');
        input.blur();
      }
      // Ctrl/Cmd+K focuses search like the dashboard palette
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') {
        event.preventDefault();
        input.focus();
      }
    });
    document.addEventListener('click', (event) => {
      if (!results.contains(event.target) && !input.contains(event.target) && !event.target.closest('.search-box')) results.classList.remove('open');
    });
  }

  function highlightQueryOnPage() {
    const params = new URLSearchParams(window.location.search);
    const q = (params.get('q') || '').trim();
    if (!q || q.length < 2) return;
    const terms = [...new Set(tokenize(q.toLowerCase()))];
    if (!terms.length) return;
    const main = $('.main-content');
    if (!main) return;
    const pattern = new RegExp(`(${terms.map(escapeRegExp).join('|')})`, 'gi');
    const walker = document.createTreeWalker(main, NodeFilter.SHOW_TEXT, {
      acceptNode: (node) => {
        if (!node.nodeValue || !pattern.test(node.nodeValue)) return NodeFilter.FILTER_REJECT;
        pattern.lastIndex = 0;
        if (node.parentElement?.closest('pre, code, script, style')) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      },
    });
    const hits = [];
    while (walker.nextNode()) hits.push(walker.currentNode);
    let firstMark = null;
    for (const node of hits.slice(0, 60)) {
      const frag = document.createDocumentFragment();
      const parts = node.nodeValue.split(pattern);
      for (const part of parts) {
        if (!part) continue;
        pattern.lastIndex = 0;
        if (pattern.test(part)) {
          const mark = document.createElement('mark');
          mark.className = 'search-hit';
          mark.textContent = part;
          frag.appendChild(mark);
          if (!firstMark) firstMark = mark;
        } else {
          frag.appendChild(document.createTextNode(part));
        }
      }
      node.replaceWith(frag);
    }
    // If arrival included an anchor the browser already jumped; otherwise jump to first hit.
    if (firstMark && !window.location.hash) {
      firstMark.scrollIntoView({ block: 'center', behavior: 'smooth' });
    }
    // Clean ?q= from the URL without reloading
    const url = new URL(window.location.href);
    url.searchParams.delete('q');
    window.history.replaceState(null, '', url.pathname + url.hash);
  }

  function setupSectionObserver() {
    const links = $$('[data-section-link]');
    const headings = links.map((link) => $(link.getAttribute('href'))).filter(Boolean);
    if (!headings.length || !('IntersectionObserver' in window)) return;
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          links.forEach((link) => link.classList.toggle('active', link.getAttribute('href') === `#${entry.target.id}`));
        }
      });
    }, { rootMargin: '-18% 0px -70% 0px', threshold: 0 });
    headings.forEach((heading) => observer.observe(heading));
  }

  document.addEventListener('DOMContentLoaded', () => {
    setActiveNavigation();
    setupMobileMenu();
    setupSyntaxHighlighting();
    setupCopyButtons();
    setupTabs();
    setupSearch();
    highlightQueryOnPage();
    setupSectionObserver();
  });
})();
